import { readFileSync,writeFileSync } from 'node:fs';
import {compileDecisionScripts} from '@wildshard/sharddev/buildDecisionScripts';
import {CONTRACT_PROGRAM_SCRIPT,contractProgramRegistries} from '<checkouts>/shard-pine-hollow/src/generators/contractProgram.ts';
const source='<checkouts>/shard-pine-hollow';
const sources=new Map(['contracts','contractsRandom','contractsRules'].map(name=>[`behaviour/${name}.as`,readFileSync(`${source}/src/behaviour/${name}.as`,'utf8')]));
const built=await compileDecisionScripts([CONTRACT_PROGRAM_SCRIPT],contractProgramRegistries(),sources,{asLineCeiling:256,singleSignal:true});
const script=built.rows[0],bytes=built.blobs[0].bytes;
writeFileSync('test/fixtures/frozen/contract-catalogue.json',JSON.stringify({...JSON.parse(readFileSync(source+'/src/data/contracts.json','utf8')),program:{script,bytes:Buffer.from(bytes).toString('base64')}})+'\n');
